SELECT "School Name", "District Name", "County Name", "Percent (%) Eligible FRPM (K-12)"
FROM frpm
WHERE "Academic Year" = '2014-2015' AND "Percent (%) Eligible FRPM (K-12)" > 70;

SELECT "School Name", "Enrollment (K-12)"
FROM frpm
WHERE "Enrollment (K-12)" < 200;

